with lines as (select id, plan, effective_from, currency, explode(discounts) as element from price_tiers) select case when element >= 70 then 'PREMIUM' else 'STANDARD' end as element_tier, count(case when plan = 'basic' then 1 end) as basic_count, count(*) filter (where currency = 'EUR') as eur_rows, count(*) filter (where plan = 'basic') as basic_rows, max(element) filter (where plan = 'pro') as pro_max_element from lines group by case when element >= 70 then 'PREMIUM' else 'STANDARD' end order by basic_rows desc nulls last
